import{J as t,o,c as a,K as d}from"./chunks/framework.BdCQ0ow3.js";const p=JSON.parse('{"title":"01 · Model I/O","description":"01 · Model I/O的完整学习记录，保留原笔记中的方法、示例与代码。","frontmatter":{"title":"01 · Model I/O","date":"2026-11-06","description":"01 · Model I/O的完整学习记录，保留原笔记中的方法、示例与代码。","category":"AI 学习","folder":"ai/langchain","order":1,"sourceNote":"ai-agents-from-zero/1、Model-IO.md","imported":true},"headers":[{"level":2,"title":"1、定义:","slug":"1定义","link":"#1定义","children":[]},{"level":2,"title":"2、Format","slug":"2format","link":"#2format","children":[]},{"level":2,"title":"3、Predict","slug":"3predict","link":"#3predict","children":[{"level":3,"title":"3.1、三种模型抽象","slug":"31三种模型抽象","link":"#31三种模型抽象","children":[]},{"level":3,"title":"3.2、核心调控参数","slug":"32核心调控参数","link":"#32核心调控参数","children":[]},{"level":3,"title":"3.3、产生的结果: AIMessage 拆解","slug":"33产生的结果-aimessage-拆解","link":"#33产生的结果-aimessage-拆解","children":[]},{"level":3,"title":"3.4、模型接入方式:","slug":"34模型接入方式","link":"#34模型接入方式","children":[]},{"level":3,"title":"3.5、选型建议:","slug":"35选型建议","link":"#35选型建议","children":[]}]},{"level":2,"title":"4、Parse","slug":"4parse","link":"#4parse","children":[]}],"relativePath":"posts/ai/langchain/01-model-io.md","filePath":"posts/ai/langchain/01-model-io.md"}'),r={name:"posts/ai/langchain/01-model-io.md"};function l(i,e,n,s,c,h){return o(),a("div",null,[...e[0]||(e[0]=[d('<h1 id="01-model-io" tabindex="-1">01 · Model I/O <a class="header-anchor" href="#01-model-io" aria-label="Permalink to &quot;01 · Model I/O&quot;">​</a></h1><blockquote><p>以下保留原学习资料的章节结构与版本语境；示例依赖对应环境，接入真实项目时需按所用版本配置。</p></blockquote><blockquote><p><strong>迁移校订</strong></p><ul><li>temperature 的取值范围、正文内容结构和元数据键因模型与 provider 而异；finish_reason 是常见结束原因键示例，并非所有集成的统一字段。temperature=0 不保证严格复现。</li></ul></blockquote><div><h2 id="1定义" tabindex="-1">1、定义: <a class="header-anchor" href="#1定义" aria-label="Permalink to &quot;1、定义:&quot;">​</a></h2><p><strong>Model I/O</strong> 是 LangChain 中专门负责&quot;<strong>如何和模型打交道</strong>&quot;的模块。它关心的就是: <strong>模型输入怎么组织、模型怎么调用、模型输出怎么处理</strong>, 这三件事加在一起就是 Model I/O 一句话定义: <mark>🟢<strong>Model I/O = Format（输入格式化）→ Predict（模型调用）→ Parse（输出解析）</strong></mark><img src="/blog-pages/notes-assets/ac01da084a734f385d4d.png" alt="01 · Model I/O 图示" loading="lazy"><strong>通俗比喻（点外卖）:</strong></p><ul><li>Format: 像下单前把需求写清楚, 例如要不要辣</li><li>Predict: 像把订单交给餐厅处理。可以切换不同餐厅</li><li>Parse: 像外卖到了之后先分装、贴标签</li></ul><h2 id="2format" tabindex="-1">2、Format <a class="header-anchor" href="#2format" aria-label="Permalink to &quot;2、Format&quot;">​</a></h2><p>关于<strong>Format</strong>的核心重点请跳转<a href="/blog-pages/posts/ai/langchain/02-prompts.html">2、Prompt</a>!</p><h2 id="3predict" tabindex="-1">3、Predict <a class="header-anchor" href="#3predict" aria-label="Permalink to &quot;3、Predict&quot;">​</a></h2><p><strong>Predict ( 模型调用 )</strong> 是 Model I/O 中最核心的部分。</p><h3 id="31三种模型抽象" tabindex="-1">3.1、三种模型抽象 <a class="header-anchor" href="#31三种模型抽象" aria-label="Permalink to &quot;3.1、三种模型抽象&quot;">​</a></h3><p>LangChain 在 Predict 阶段抹平了各家厂商的 API 差异，核心划分为三种模型：</p><table tabindex="0"><thead><tr><th>模型类型</th><th>输入 (Input)</th><th>输出 (Output)</th><th>核心特点与场景</th></tr></thead><tbody><tr><td><strong>Chat Model</strong> <br><em>(核心重点)</em></td><td>消息列表 <code>[Message]</code> 或 字符串</td><td><code>AIMessage</code></td><td>天然支持角色身份、工具调用与上下文记忆（Agent 主流路线）</td></tr><tr><td><strong>LLM</strong> <br><em>(传统纯文本)</em></td><td>纯文本字符串</td><td>纯文本字符串</td><td>旧版纯文本续写接口，无结构化角色，现代 Agent 中较少使用</td></tr><tr><td><strong>Embeddings</strong></td><td>文本或文本列表</td><td>浮点数向量 <code>[0.12, ...]</code></td><td>只计算语义向量，不生成对话文本，用于 RAG 检索</td></tr></tbody></table><h3 id="32核心调控参数" tabindex="-1">3.2、核心调控参数 <a class="header-anchor" href="#32核心调控参数" aria-label="Permalink to &quot;3.2、核心调控参数&quot;">​</a></h3><p>1.<code>temperature</code>（采样温度, 通常 0-2）</p><ul><li><code>0</code>：通常降低采样随机性，但不能保证相同输入的输出完全确定。</li><li><code>0.7</code>: 平衡严谨与发散</li><li><code>1.5+</code>: 高度随机、发散甚至跳跃 2.<code>max_tokens</code>: 单次回复的最大 Token 上限, 控制生成长度与防刷扣费 3.<code>timeout</code>&amp;<code>max_retries</code>: 网络超时上限与异常自动重试次数 4.<code>stop</code>: 停止词列表, 模型一旦生成该词即强行中断退出</li></ul><h3 id="33产生的结果-aimessage-拆解" tabindex="-1">3.3、产生的结果: <code>AIMessage</code> 拆解 <a class="header-anchor" href="#33产生的结果-aimessage-拆解" aria-label="Permalink to &quot;3.3、产生的结果: `AIMessage` 拆解&quot;">​</a></h3><p>调用 <code>response = model.invoke(...)</code> 拿到的<strong>不是纯文本</strong>, 而是一个包含丰富元数据的复合对象:</p><ul><li><code>response.content</code>: 模型回复的<strong>正文文本</strong></li><li><code>response.usage_metadata</code>: <strong>Token 用量统计</strong>（包含 <code>input_tokens</code>、<code>output_tokens</code>、<code>total_tokens</code>）, 用于算力计费和成本监控</li><li><code>response.response_metadata</code>: 底层的原始元数据（包含厂商模型名、<code>finish_reason</code>结束原因等）</li><li><code>response.tool_calls</code>: 模型若决定调用外部工具, 工具名与参数存放在这里（Agent核心机制）</li></ul><h3 id="34模型接入方式" tabindex="-1">3.4、模型接入方式: <a class="header-anchor" href="#34模型接入方式" aria-label="Permalink to &quot;3.4、模型接入方式:&quot;">​</a></h3><table tabindex="0"><thead><tr><th>接法</th><th>典型代表</th><th>适合什么</th></tr></thead><tbody><tr><td><strong>官方 SDK 直连</strong></td><td><code>openai.OpenAI</code></td><td>只做底层 API 调用，不打算用 LangChain 编排</td></tr><tr><td><strong>LangChain provider / 模型类</strong></td><td><code>ChatOpenAI</code>、<code>ChatDeepSeek</code>、<code>ChatTongyi</code></td><td>已经决定使用某个 provider 包，希望结合 LangChain 生态</td></tr><tr><td><strong>LangChain 统一入口</strong></td><td><code>init_chat_model(...)</code></td><td>新项目推荐，适合统一风格、减少对具体类名的依赖</td></tr><tr><td>可以看作三种层次:</td><td></td><td></td></tr></tbody></table><ul><li>OpenAI SDK: 更底层, 最贴近原生 API</li><li>具体模型类: LangChain 生态中的 provider 封装</li><li>统一入口: LangChain 1.x 更推荐的高层入口</li></ul><h3 id="35选型建议" tabindex="-1">3.5、选型建议: <a class="header-anchor" href="#35选型建议" aria-label="Permalink to &quot;3.5、选型建议:&quot;">​</a></h3><p><strong>第一层选择：先决定是不是要进入 LangChain 体系。</strong></p><ul><li>只是简单调用：原生 SDK 就够</li><li>要继续做 Prompt、Parser、LCEL、Agent：尽早进入 LangChain 模型对象</li></ul><p><strong>第二层选择：在 LangChain 里决定用 provider 类还是统一入口。</strong></p><ul><li>新项目优先考虑 <code>init_chat_model</code></li><li>维护旧项目或已有 provider 类代码时，直接用 <code>ChatOpenAI</code> / <code>ChatDeepSeek</code> / <code>ChatTongyi</code> 也完全合理</li></ul><p><strong>第三层选择：决定走兼容接口还是原生 provider。</strong></p><ul><li>想统一风格、少记类名：兼容接口路线更简单</li><li>想贴近厂商原生能力：原生 provider 路线通常表达更完整</li></ul><h2 id="4parse" tabindex="-1">4、Parse <a class="header-anchor" href="#4parse" aria-label="Permalink to &quot;4、Parse&quot;">​</a></h2><p>关于<strong>Parse</strong>的核心重点请跳转[[3.Parse]]!</p></div><hr><p><em>原笔记：ai-agents-from-zero/1、Model-IO.md。迁移时保留原文结构，完成链接、附件和已识别问题的适配。</em></p>',6)])])}const m=t(r,[["render",l]]);export{p as __pageData,m as default};
